const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = v => new Intl.NumberFormat('uz-UZ').format(v).replace(/,/g, ' ') + ' so‘m';
const image = id => `https://images.unsplash.com/${id}?auto=format&fit=crop&w=700&q=80`;
const photos = {burger:'food-burger.svg',pizza:'food-pizza.svg',national:'food-national.svg',salad:'food-salad.svg',dessert:'food-dessert.svg',drink:'food-drink.svg'};
const safeImage = (url,fallback) => /^(https:\/\/|food-[a-z]+\.svg$)/i.test(url || '') ? url : fallback;
const fallbackPhoto = p => /pitsa|pizza/i.test(p.name)?photos.pizza:/burger|lavash|fast/i.test(p.name+' '+p.cat)?photos.burger:/salat/i.test(p.cat)?photos.salad:/ichimlik/i.test(p.cat)?photos.drink:/shirin/i.test(p.cat)?photos.dessert:photos.national;
const sampleMenus = [
  ['Oshxona','Milliy taomlar','national',[['To‘y oshi',38000],['Qozon kabob',56000],['Manti',32000],['Achchiq-chuchuk',12000]]],
  ['Burger joy','Fast food','burger',[['Mol go‘shtli burger',42000],['Chizburger',46000],['Tovuq burger',35000],['Kartoshka fri',16000]]],
  ['Pitsa uyi','Pitsa','pizza',[['Pepperoni pitsa',69000],['Margarita',55000],['To‘rt pishloq',79000],['Tovuqli pitsa',65000]]],
  ['Yashil kosa','Salatlar','salad',[['Sezar salati',32000],['Yangi sabzavotlar',25000],['Tovuqli salat',34000],['Vitamin salat',22000]]],
  ['Shirin tanaffus','Shirinliklar','dessert',[['Shokoladli tort',28000],['Chizkeyk',32000],['Medovik',25000],['Qulupnayli desert',29000]]],
  ['Choy & suhbat','Ichimliklar','drink',[['Limonli choy',12000],['Moxito',22000],['Qulupnay limonad',24000],['Amerikano',18000]]]
];
const demos = sampleMenus.map(([name,cat,photo,items],index) => ({id:'sample-'+index,name,demo:true,open:true,address:'Namuna restoran',categories:[cat],branches:[],cover:photos[photo],menu:items.map(([name,price],i)=>({id:i+1,name,price,cat,img:photos[photo],stop:false}))}));
const categories = [['Barchasi','🍽️'],['Milliy taomlar','🍲'],['Fast food','🍔'],['Pitsa','🍕'],['Salatlar','🥗'],['Shirinliklar','🍰'],['Ichimliklar','🥤']];
let restaurants=[],selected=null,category='Barchasi',menuCategory='Barchasi',query='',onlyOpen=false,loading=true,loadFailed=false,toastTimer,pendingSwitch=null,submitting=false;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{}}
let cart=read('birga-food-cart-v1',{restaurantId:null,items:[],requestId:null});
if(!cart || !Array.isArray(cart.items) || cart.items.some(i=>!Number.isInteger(i.id)||!Number.isInteger(i.qty)||i.qty<1||i.qty>50))cart={restaurantId:null,items:[],requestId:null};
let address=read('birga-food-address','');if(typeof address!=='string')address='';
const show = id => {if(!$(id).open)$(id).showModal()};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function saveCart(){persist('birga-food-cart-v1',cart);$('#cart-count').textContent=cart.items.reduce((a,i)=>a+i.qty,0)}
function setAddress(value){address=value.trim();persist('birga-food-address',address);$('#address-label').textContent=address||'Manzilni kiriting'}
function info(title,html){$('#info-title').textContent=title;$('#info-body').innerHTML=html;show('#info-dialog')}
function renderCategories(){const extras=[...new Set(restaurants.flatMap(r=>r.categories))].filter(c=>!categories.some(x=>x[0]===c));$('#categories').innerHTML=[...categories,...extras.map(c=>[c,'🍴'])].map(([c,icon])=>`<button class="category ${category===c?'active':''}" data-category="${esc(c)}" aria-pressed="${category===c}"><span aria-hidden="true">${icon}</span>${esc(c)}</button>`).join('')}
function renderRestaurants(){renderCategories();const list=restaurants.filter(r=>(!onlyOpen||r.open)&&(category==='Barchasi'||r.menu.some(p=>p.cat===category))&&(!query||(r.name+' '+r.menu.map(p=>p.name).join(' ')).toLocaleLowerCase().includes(query)));
  $('#catalog-note').innerHTML=loading?'Restoranlar yuklanmoqda…':loadFailed?'Restoranlarni yuklab bo‘lmadi. <button class="filter" id="retry-load">Qayta urinish</button>':restaurants.some(r=>r.demo)?'Namuna menyular: tanlash va savatni sinab ko‘ring. Haqiqiy buyurtma uchun restoran egasi kabinetda menyu qo‘shishi kerak.':`${list.length} ta restoran · To‘lov: yetkazilganda naqd. Yetkazish shartlarini restoran tasdiqlaydi.`;
  $('#restaurants').innerHTML=list.map(r=>`<button class="restaurant" data-restaurant="${esc(r.id)}"><div class="restaurant-picture"><img src="${esc(safeImage(r.cover||r.menu.find(p=>p.img)?.img, fallbackPhoto(r.menu[0])))}" alt="${esc(r.name)} taomlari" loading="lazy"><span class="tag">${r.demo?'Namuna menyu':r.open?'Buyurtma qabul qilmoqda':'Hozir yopiq'}</span></div><h3>${esc(r.name)}</h3><p>${esc([...new Set(r.menu.map(p=>p.cat))].join(' · '))}</p><div class="restaurant-meta"><span>${money(Math.min(...r.menu.map(p=>p.price)))} dan</span><b>Menyuni ko‘rish ↗</b></div></button>`).join('')||(!loading?'<div class="empty">Restoran topilmadi.<br>Boshqa taom yoki restoran nomini qidiring.</div>':'');
}
function selectRestaurant(id){selected=restaurants.find(r=>r.id===id);if(!selected)return;menuCategory=category!=='Barchasi'&&selected.menu.some(p=>p.cat===category)?category:'Barchasi';renderMenu();$('#menu-section').scrollIntoView({behavior:'smooth'})}
function renderMenu(){if(!selected)return;$('#menu-section').hidden=false;$('#menu-title').textContent=selected.name;$('#menu-kicker').textContent=selected.demo?'NAMUNA MENYU':selected.open?'BUYURTMA QABUL QILMOQDA':'RESTORAN HOZIR YOPIQ';const cats=['Barchasi',...new Set(selected.menu.map(p=>p.cat))];$('#menu-tabs').innerHTML=cats.map(c=>`<button class="${c===menuCategory?'active':''}" data-menu-category="${esc(c)}">${esc(c)}</button>`).join('');const list=selected.menu.filter(p=>(menuCategory==='Barchasi'||p.cat===menuCategory)&&(!query||(p.name+' '+selected.name).toLocaleLowerCase().includes(query)));$('#menu-grid').innerHTML=list.map(p=>`<article class="food-card"><img src="${esc(safeImage(p.img,fallbackPhoto(p)))}" alt="${esc(p.name)}" loading="lazy"><div class="food-copy"><h3>${esc(p.name)}</h3><p>${esc(p.cat)}${p.stop?' · Hozir mavjud emas':''}</p><div class="food-bottom"><strong>${money(p.price)}</strong><button class="add" data-add="${p.id}" ${p.stop||!selected.open?'disabled':''} aria-label="${esc(p.name)} savatga qo‘shish">+</button></div></div></article>`).join('')||'<div class="empty">Bu bo‘limda taom topilmadi.</div>'}
function add(id){if(submitting)return;const p=selected?.menu.find(p=>p.id===id);if(!p||p.stop||!selected.open)return;if(cart.items.length&&cart.restaurantId!==selected.id){pendingSwitch={restaurantId:selected.id,id};info('Boshqa restorandan buyurtma?',`<p>Bitta savatda bitta restoran taomlari bo‘lishi mumkin. Yangi savat ochilganda avvalgi taomlar o‘chadi.</p><button class="primary" id="confirm-switch">Yangi savat ochish</button>`);return}cart.restaurantId=selected.id;const row=cart.items.find(i=>i.id===id);if(row){if(row.qty>=50){toast('Bitta taomdan ko‘pi bilan 50 ta');return}row.qty++}else cart.items.push({id,qty:1});cart.requestId=crypto.randomUUID();saveCart();toast('Taom savatga qo‘shildi')}
function cartRestaurant(){return restaurants.find(r=>r.id===cart.restaurantId)}
function cartTotal(r){return cart.items.reduce((sum,i)=>sum+(r.menu.find(p=>p.id===i.id)?.price||0)*i.qty,0)}
function renderCart(){const r=cartRestaurant();if(!cart.items.length){$('#cart-body').innerHTML='<div class="empty">Hali hech narsa tanlamadingiz.<br>Menyudan mazali biror narsa qo‘shing.</div>';return}if(!r){$('#cart-body').innerHTML='<p>Bu restoran hozir katalogda yo‘q. Savatni tozalab, boshqa restoran tanlang.</p><button class="primary" id="clear-cart">Savatni tozalash</button>';return}
const unavailable=cart.items.some(i=>!r.menu.some(p=>p.id===i.id&&!p.stop));$('#cart-body').innerHTML=`<p><b>${esc(r.name)}</b> · Bitta restorandan buyurtma</p>${cart.items.map(i=>{const p=r.menu.find(p=>p.id===i.id);return `<div class="cart-row"><img src="${esc(safeImage(p?.img,photos.national))}" alt=""><div><h3>${esc(p?.name||'Mavjud bo‘lmagan taom')}</h3><p>${money((p?.price||0)*i.qty)}</p></div><div class="qty"><button data-qty="${i.id}" data-delta="-1" aria-label="Sonini kamaytirish">−</button><span>${i.qty}</span><button data-qty="${i.id}" data-delta="1" aria-label="Sonini oshirish" ${i.qty>=50?'disabled':''}>+</button></div></div>`}).join('')}<div class="totals"><p><span>Yetkazib berish</span><span>Restoran bilan kelishiladi</span></p><p><span>Taomlar jami</span><span>${money(cartTotal(r))}</span></p></div>${r.demo?'<p class="notice">Bu namuna menyu. Haqiqiy buyurtma yuborilmaydi. Haqiqiy restoran menyusi qo‘shilgach buyurtma berish ochiladi.</p>':`<form id="checkout-form"><label>Ismingiz<input name="customer" required maxlength="100" autocomplete="name" placeholder="Ismingiz"></label><label>Telefon raqamingiz<input name="phone" type="tel" required maxlength="30" autocomplete="tel" placeholder="+998 90 123 45 67" pattern="[+0-9 ()-]{12,30}"></label><label>Yetkazib berish manzili<input name="address" required maxlength="300" autocomplete="street-address" value="${esc(address)}" placeholder="Ko‘cha, uy, xonadon"></label><label>Restoran filiali<select name="branch">${r.branches.map(b=>`<option value="${b.id}">${esc(b.name)} — ${esc(b.address)}</option>`).join('')}</select></label><label>Izoh (ixtiyoriy)<textarea name="note" maxlength="2000" placeholder="Domofon, mo‘ljal yoki taom bo‘yicha istak"></textarea></label><p class="notice">To‘lov yetkazilganda naqd. Yetkazib berish narxi va vaqtini restoran telefon orqali tasdiqlaydi. Buyurtma restoran tasdiqlagach bajariladi.</p><p id="checkout-error" class="error" role="alert">${unavailable?'Savatdagi ayrim taomlar mavjud emas. Ularni olib tashlang.':!r.open?'Restoran hozir yopiq.':''}</p><button class="primary" ${unavailable||!r.open?'disabled':''}>Buyurtma yuborish · ${money(cartTotal(r))}</button></form>`}`}
async function load(){loading=true;loadFailed=false;renderRestaurants();try{const res=await fetch('/api/food/restaurants');if(!res.ok)throw Error();const data=await res.json();restaurants=data.restaurants.length?data.restaurants:demos;}catch{loadFailed=true;restaurants=[]}finally{loading=false;renderRestaurants();if(selected){selected=restaurants.find(r=>r.id===selected.id);if(selected)renderMenu();else $('#menu-section').hidden=true}}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close')){if(!submitting)b.closest('dialog').close();return}if(b.dataset.category){category=b.dataset.category;selected=null;$('#menu-section').hidden=true;renderRestaurants();$('#restaurants-section').scrollIntoView({behavior:'smooth'})}if(b.dataset.restaurant)selectRestaurant(b.dataset.restaurant);if(b.dataset.menuCategory){menuCategory=b.dataset.menuCategory;renderMenu()}if(b.dataset.add)add(Number(b.dataset.add));if(b.dataset.qty&&!submitting){const i=cart.items.find(i=>i.id===+b.dataset.qty);if(i){i.qty=Math.min(50,i.qty+Number(b.dataset.delta));cart.items=cart.items.filter(i=>i.qty>0);cart.requestId=crypto.randomUUID();saveCart();renderCart()}}if(b.id==='confirm-switch'&&pendingSwitch){cart={restaurantId:null,items:[],requestId:null};selected=restaurants.find(r=>r.id===pendingSwitch.restaurantId);$('#info-dialog').close();add(pendingSwitch.id);pendingSwitch=null}if(b.id==='clear-cart'){cart={restaurantId:null,items:[],requestId:null};saveCart();renderCart()}if(b.id==='retry-load')load()});
$('#cart-button').onclick=()=>{renderCart();show('#cart-dialog')};$('#browse').onclick=()=>$('#restaurants-section').scrollIntoView({behavior:'smooth'});$('#back-restaurants').onclick=()=>{$('#menu-section').hidden=true;selected=null;$('#restaurants-section').scrollIntoView({behavior:'smooth'})};$('#open-filter').onclick=()=>{onlyOpen=!onlyOpen;$('#open-filter').setAttribute('aria-pressed',onlyOpen);renderRestaurants()};$('#search').addEventListener('input',e=>{query=e.target.value.trim().toLocaleLowerCase();renderRestaurants();if(selected)renderMenu()});$('#address-button').onclick=()=>{$('#address-form').elements.address.value=address;show('#address-dialog')};$('#address-form').onsubmit=e=>{e.preventDefault();const value=e.target.elements.address.value.trim();if(!value)return;setAddress(value);$('#address-dialog').close();toast('Manzil saqlandi')};$('#help-button').onclick=()=>info('Bir necha bosishda buyurtma', '<p>1. Restoranni tanlang va menyusini oching.</p><p>2. Taomlarni savatga qo‘shing.</p><p>3. Telefon va manzilni kiriting, buyurtmani yuboring.</p><p>Restoran buyurtmani kabinetida ko‘radi va yetkazish shartlarini siz bilan tasdiqlaydi. To‘lov yetkazilganda naqd. Namuna restoranlardan haqiqiy buyurtma yuborilmaydi.</p>');
$('#cart-dialog').addEventListener('cancel',e=>{if(submitting)e.preventDefault()});
$('#cart-dialog').addEventListener('submit',async e=>{if(e.target.id!=='checkout-form')return;e.preventDefault();if(submitting)return;const form=e.target,r=cartRestaurant();if(!r||r.demo||!r.open)return;const values=Object.fromEntries(new FormData(form));values.customer=values.customer.trim();values.address=values.address.trim();values.phone=values.phone.replace(/[\s()-]/g,'');if(!values.customer||!values.address||!/^\+998\d{9}$/.test(values.phone)){$('#checkout-error').textContent='Ism, manzil va +998 bilan to‘liq telefon raqamini kiriting.';return}const items=cart.items.map(i=>({...i,price:r.menu.find(p=>p.id===i.id)?.price}));submitting=true;const buttons=[...$('#cart-dialog').querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);const submit=form.querySelector('.primary');submit.textContent='Yuborilmoqda…';try{const res=await fetch('/api/food/orders',{method:'POST',headers:{'Content-Type':'application/json','X-Birga-Request':'1'},body:JSON.stringify({...values,branch:Number(values.branch),restaurantId:r.id,requestId:cart.requestId,items})});const data=await res.json();if(!res.ok)throw Error(data.error||'Buyurtma yuborilmadi. Qayta urinib ko‘ring.');setAddress(values.address);cart={restaurantId:null,items:[],requestId:null};saveCart();$('#cart-body').innerHTML=`<div class="receipt-icon">✓</div><h2>Buyurtma restoranga yuborildi!</h2><p><b>${esc(data.order.restaurant)} · #${data.order.id}</b></p><p>Taomlar jami: <b>${money(data.order.total)}</b></p><p>Restoran qabul qilishi va yetkazish shartlarini tasdiqlashi kutilmoqda. Telefoningizni yoningizda saqlang.</p><button class="primary" data-close>Yaxshi, rahmat</button>`;}catch(error){$('#checkout-error').textContent=error.message;submit.textContent='Qayta yuborish · '+money(cartTotal(r));}finally{submitting=false;buttons.forEach(b=>b.disabled=false)}});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&!e.target.dataset.fallback){e.target.dataset.fallback='1';e.target.src='food-placeholder.svg'}},true);
setAddress(address);saveCart();load();
